# Login smoke test
$login = Invoke-WebRequest -Uri "http://localhost:3000/api/login" -Method POST -ContentType "application/json" -Headers @{"X-Student-Id"="23127255"} -Body '{"email":"smoke_env_check@test.com","password":"Smoke123!"}' -ErrorAction SilentlyContinue
if ($login) { "LOGIN: HTTP $($login.StatusCode)"; $login.Content | ConvertFrom-Json | Select-Object -Property * } else { "LOGIN: unreachable" }

# Products smoke test (no auth)
$prod = Invoke-WebRequest -Uri "http://localhost:3000/api/products" -Method GET -Headers @{"X-Student-Id"="23127255"} -ErrorAction SilentlyContinue
if ($prod) { "PRODUCTS: HTTP $($prod.StatusCode)"; ($prod.Content | ConvertFrom-Json).Count; "products returned" } else { "PRODUCTS: unreachable" }

# Verify admin login
$admin = Invoke-WebRequest -Uri "http://localhost:3000/api/login" -Method POST -ContentType "application/json" -Headers @{"X-Student-Id"="23127255"} -Body '{"email":"admin@eshop.com","password":"Admin123!"}' -ErrorAction SilentlyContinue
if ($admin) { "ADMIN LOGIN: HTTP $($admin.StatusCode)"; $admin.Content } else { "ADMIN LOGIN: failed" }

# Verify test user login
$user = Invoke-WebRequest -Uri "http://localhost:3000/api/login" -Method POST -ContentType "application/json" -Headers @{"X-Student-Id"="23127255"} -Body '{"email":"test@eshop.com","password":"Test1234!"}' -ErrorAction SilentlyContinue
if ($user) { "USER LOGIN: HTTP $($user.StatusCode)"; $user.Content } else { "USER LOGIN: failed" }

